import React, { useEffect, useRef } from "react";
import * as THREE from "three";
import { OrbitControls } from "three/addons/controls/OrbitControls.js";
import { RoundedBoxGeometry } from "three/addons/geometries/RoundedBoxGeometry.js";
import { FIGURES } from "./figures";

const ROOM = { width: 36, depth: 26, height: 10 };
const STOP_POINT = { x: 10, z: 4.4 };
const CAMERA_HOME = new THREE.Vector3(0, 15, 26);
const CAMERA_TARGET = new THREE.Vector3(0, 1.1, 0);

const material = (color, extra = {}) =>
  new THREE.MeshStandardMaterial({ color, roughness: 0.68, metalness: 0.08, ...extra });

function mesh(parent, geometry, surface, position, scale) {
  const object = new THREE.Mesh(geometry, surface);
  object.position.set(...position);
  if (scale) object.scale.set(...scale);
  object.castShadow = true;
  object.receiveShadow = true;
  parent.add(object);
  return object;
}

function ball(parent, surface, position, scale, detail = 22) {
  return mesh(
    parent,
    new THREE.SphereGeometry(1, detail, Math.max(12, Math.round(detail * 0.72))),
    surface,
    position,
    scale
  );
}

function roundedBox(parent, surface, position, size, radius = 0.12) {
  const safeRadius = Math.min(radius, ...size.map((dimension) => dimension * 0.44));
  return mesh(
    parent,
    new RoundedBoxGeometry(size[0], size[1], size[2], 3, safeRadius),
    surface,
    position
  );
}

function cylinder(parent, surface, position, radiusTop, radiusBottom, height, segments = 18) {
  return mesh(
    parent,
    new THREE.CylinderGeometry(radiusTop, radiusBottom, height, segments),
    surface,
    position
  );
}

function cone(parent, surface, position, radius, height, rotation = 0) {
  const object = mesh(parent, new THREE.ConeGeometry(radius, height, 14), surface, position);
  object.rotation.z = rotation;
  return object;
}

function line(parent, surface, points, radius = 0.025) {
  const curve = new THREE.CatmullRomCurve3(
    points.map((point) => new THREE.Vector3(...point))
  );
  return mesh(parent, new THREE.TubeGeometry(curve, 20, radius, 8, false), surface, [0, 0, 0]);
}

function star(parent, surface, position, size = 0.38, depth = 0.12) {
  const shape = new THREE.Shape();
  for (let index = 0; index < 10; index += 1) {
    const radius = index % 2 ? size * 0.44 : size;
    const angle = Math.PI / 2 + (index * Math.PI) / 5;
    const x = Math.cos(angle) * radius;
    const y = Math.sin(angle) * radius;
    if (index === 0) shape.moveTo(x, y);
    else shape.lineTo(x, y);
  }
  shape.closePath();
  const geometry = new THREE.ExtrudeGeometry(shape, {
    depth,
    bevelEnabled: true,
    bevelSegments: 2,
    steps: 1,
    bevelSize: 0.04,
    bevelThickness: 0.04,
  });
  return mesh(parent, geometry, surface, position);
}

function eye(parent, x, y, z, size, glow = false) {
  const white = material(glow ? "#b9fff0" : "#fff9ee", {
    roughness: 0.18,
    emissive: glow ? "#4bd9bf" : "#000000",
    emissiveIntensity: glow ? 0.42 : 0,
  });
  const pupil = material(glow ? "#153f42" : "#172029", { roughness: 0.16 });
  ball(parent, white, [x, y, z], [size, size * 1.28, size * 0.42], 18);
  ball(parent, pupil, [x + size * 0.08, y - size * 0.03, z + size * 0.34], [size * 0.43, size * 0.6, size * 0.26], 16);
  ball(parent, material("#ffffff", { roughness: 0.05, emissive: "#ffffff", emissiveIntensity: 0.12 }), [x + size * 0.19, y + size * 0.2, z + size * 0.52], [size * 0.13, size * 0.15, size * 0.08], 10);
}

function addNameSprite(parent, label, accent) {
  const canvas = document.createElement("canvas");
  canvas.width = 384;
  canvas.height = 80;
  const context = canvas.getContext("2d");
  context.fillStyle = "rgba(8, 15, 17, .88)";
  context.beginPath();
  context.roundRect(4, 4, 376, 72, 22);
  context.fill();
  context.strokeStyle = `${accent}99`;
  context.lineWidth = 3;
  context.stroke();
  context.fillStyle = accent;
  context.beginPath();
  context.arc(39, 40, 9, 0, Math.PI * 2);
  context.fill();
  context.fillStyle = "#f5f2e8";
  context.font = "600 30px Arial, sans-serif";
  context.fillText(label.toUpperCase(), 64, 51, 290);
  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  const sprite = new THREE.Sprite(
    new THREE.SpriteMaterial({ map: texture, transparent: true, depthWrite: false })
  );
  sprite.scale.set(2.25, 0.48, 1);
  sprite.position.set(0, 2.55, 0);
  parent.add(sprite);
  sprite.userData.canvas = canvas;
  sprite.userData.texture = texture;
  return sprite;
}

function addArm(parent, surface, x, side, long = false) {
  const pivot = new THREE.Group();
  pivot.position.set(x, 1.03, 0);
  parent.add(pivot);
  const length = long ? 0.5 : 0.42;
  const arm = cylinder(pivot, surface, [side * 0.17, -length * 0.48, 0], 0.13, 0.18, length, 14);
  arm.rotation.z = side * -0.26;
  ball(pivot, surface, [side * 0.2, -length, 0.03], [0.15, 0.15, 0.15], 14);
  return pivot;
}

function makeModel(figure) {
  const root = new THREE.Group();
  const arms = [];

  if (figure.id === "claude") {
    const fur = material("#e9955f", { roughness: 0.84 });
    const cream = material("#ffe9c9", { roughness: 0.78 });
    const innerEar = material("#a9524e", { roughness: 0.76 });
    ball(root, fur, [0, 0.94, 0], [0.72, 0.65, 0.57]);
    ball(root, fur, [0, 1.43, 0.03], [0.7, 0.64, 0.58]);
    cone(root, fur, [-0.43, 1.95, 0], 0.25, 0.63, -0.3);
    cone(root, fur, [0.43, 1.95, 0], 0.25, 0.63, 0.3);
    cone(root, innerEar, [-0.43, 1.95, 0.16], 0.12, 0.38, -0.3);
    cone(root, innerEar, [0.43, 1.95, 0.16], 0.12, 0.38, 0.3);
    ball(root, cream, [0, 1.2, 0.49], [0.44, 0.28, 0.2]);
    eye(root, -0.23, 1.5, 0.51, 0.12);
    eye(root, 0.23, 1.5, 0.51, 0.12);
    ball(root, material("#713e36"), [0, 1.27, 0.68], [0.08, 0.055, 0.045], 12);
    line(root, material("#91493f"), [[0, 1.22, 0.68], [0, 1.14, 0.69], [-0.09, 1.12, 0.65]], 0.018);
    line(root, material("#91493f"), [[0, 1.14, 0.69], [0.09, 1.12, 0.65]], 0.018);
    line(root, fur, [[-0.16, 0.9, -0.36], [-0.52, 0.92, -0.7], [-0.66, 1.12, -0.72]], 0.17);
    arms.push(addArm(root, fur, -0.6, -1), addArm(root, fur, 0.6, 1));
  } else if (figure.id === "chatgpt") {
    const shell = material("#22bc96", { roughness: 0.36, metalness: 0.12 });
    const glass = material("#133a3b", { roughness: 0.2, metalness: 0.28 });
    roundedBox(root, shell, [0, 0.94, 0], [1.08, 1.16, 0.72], 0.18);
    roundedBox(root, glass, [0, 1.48, 0.38], [0.83, 0.55, 0.1], 0.12);
    eye(root, -0.2, 1.55, 0.46, 0.075, true);
    eye(root, 0.2, 1.55, 0.46, 0.075, true);
    cylinder(root, shell, [0, 1.97, 0], 0.035, 0.035, 0.22, 10);
    ball(root, material("#ecce72", { emissive: "#c29b39", emissiveIntensity: 0.28 }), [0, 2.1, 0], [0.07, 0.07, 0.07], 12);
    cylinder(root, shell, [-0.63, 1.14, 0], 0.15, 0.15, 0.28, 16).rotation.z = Math.PI / 2;
    cylinder(root, shell, [0.63, 1.14, 0], 0.15, 0.15, 0.28, 16).rotation.z = Math.PI / 2;
    arms.push(addArm(root, shell, -0.53, -1), addArm(root, shell, 0.53, 1));
    roundedBox(root, material("#d9e9db"), [0, 0.23, 0.04], [0.78, 0.18, 0.68], 0.08);
    roundedBox(root, material("#1d4541"), [0, 0.22, 0.4], [0.16, 0.1, 0.025], 0.04);
  } else if (figure.id === "grok") {
    const coat = material("#d5e0e8", { roughness: 0.52, metalness: 0.16 });
    const visor = material("#121c2a", { roughness: 0.22, metalness: 0.42 });
    const cyan = material("#83f3ff", { emissive: "#2dd9f2", emissiveIntensity: 0.8, roughness: 0.22 });
    ball(root, coat, [0, 0.94, 0], [0.69, 0.63, 0.55]);
    ball(root, coat, [0, 1.43, 0.04], [0.72, 0.64, 0.58]);
    cone(root, coat, [-0.48, 1.94, -0.02], 0.26, 0.72, -0.26);
    cone(root, coat, [0.48, 1.94, -0.02], 0.26, 0.72, 0.26);
    roundedBox(root, visor, [0, 1.45, 0.52], [1.0, 0.45, 0.14], 0.12);
    const eyeShape = new THREE.Shape();
    eyeShape.moveTo(-0.15, 0.08); eyeShape.lineTo(0.15, 0.16); eyeShape.lineTo(0.02, -0.14); eyeShape.closePath();
    const cyanGeometry = new THREE.ShapeGeometry(eyeShape);
    mesh(root, cyanGeometry, cyan, [-0.23, 1.42, 0.603], [0.72, 0.72, 0.72]);
    mesh(root, cyanGeometry, cyan, [0.23, 1.42, 0.603], [-0.72, 0.72, 0.72]);
    line(root, material("#f5fbff", { metalness: 0.35 }), [[-0.57, 1.82, 0], [-0.82, 2.04, -0.06]], 0.035);
    arms.push(addArm(root, coat, -0.59, -1), addArm(root, coat, 0.59, 1));
  } else if (figure.id === "qwen") {
    const lilac = material("#a58be8", { roughness: 0.55 });
    const lilacLight = material("#d5c7ff", { roughness: 0.48 });
    [[0, 1.02, 0, 0.58], [-0.42, 1.18, 0, 0.43], [0.42, 1.18, 0, 0.43], [-0.24, 1.55, 0, 0.42], [0.24, 1.55, 0, 0.42], [0, 1.69, 0, 0.38]].forEach(
      ([x, y, z, size]) => ball(root, lilac, [x, y, z], [size, size * 0.84, size * 0.78])
    );
    ball(root, lilacLight, [-0.34, 1.75, 0.15], [0.17, 0.23, 0.2], 16);
    ball(root, lilacLight, [0.34, 1.75, 0.15], [0.17, 0.23, 0.2], 16);
    eye(root, -0.22, 1.34, 0.43, 0.09);
    eye(root, 0.22, 1.34, 0.43, 0.09);
    star(root, material("#ffd36b", { metalness: 0.15, roughness: 0.3, emissive: "#dca139", emissiveIntensity: 0.22 }), [0, 2.18, 0.05], 0.3, 0.12);
    arms.push(addArm(root, lilac, -0.48, -1), addArm(root, lilac, 0.48, 1));
  } else {
    const jacketColors = {
      altman: "#26373b",
      amodei: "#263744",
      musk: "#161f2d",
      huang: "#171b1b",
    };
    const jacket = material(jacketColors[figure.id], { roughness: 0.58, metalness: figure.id === "huang" ? 0.18 : 0.05 });
    const shirt = material(figure.id === "huang" ? "#343c3b" : "#e8e2d5", { roughness: 0.72 });
    const hair = material(
      figure.id === "huang" ? "#4c4a43" : figure.id === "musk" ? "#443630" : "#403331",
      { roughness: 0.82 }
    );
    const face = material(figure.id === "huang" ? "#d9a77f" : "#d99a76", { roughness: 0.76 });
    roundedBox(root, jacket, [0, 0.78, 0], [1.03, 0.92, 0.66], 0.2);
    ball(root, shirt, [0, 1.15, 0.35], [0.32, 0.48, 0.12]);
    const tieColor = figure.id === "altman" ? "#6d9d8d" : figure.id === "huang" ? "#88c946" : "#28313a";
    const tie = material(tieColor, { roughness: 0.5, metalness: 0.08 });
    if (figure.id !== "musk" && figure.id !== "amodei") {
      cone(root, tie, [0, 0.94, 0.48], 0.12, 0.56, Math.PI);
    }
    cylinder(root, skinMaterial(face), [0, 1.33, 0], 0.18, 0.2, 0.16, 16);
    ball(root, face, [0, 1.78, 0.02], [0.57, 0.67, 0.49]);
    ball(root, face, [-0.57, 1.73, 0.02], [0.11, 0.18, 0.12], 14);
    ball(root, face, [0.57, 1.73, 0.02], [0.11, 0.18, 0.12], 14);
    if (figure.id === "huang") {
      ball(root, hair, [0, 2.12, -0.02], [0.55, 0.28, 0.48]);
    } else {
      ball(root, hair, [0, 2.22, -0.03], [0.57, 0.28, 0.5]);
      ball(root, hair, [-0.43, 2.03, -0.02], [0.2, 0.31, 0.36], 16);
      if (figure.id === "musk") ball(root, hair, [0.31, 2.13, 0.1], [0.28, 0.18, 0.36], 16);
    }
    const eyeMat = material("#fff2e7", { roughness: 0.22 });
    [-0.2, 0.2].forEach((x) => {
      ball(root, eyeMat, [x, 1.79, 0.444], [0.085, 0.058, 0.036], 14);
      ball(root, material("#25303a", { roughness: 0.2 }), [x, 1.78, 0.478], [0.032, 0.044, 0.02], 12);
    });
    line(root, material("#884e45"), [[-0.1, 1.53, 0.47], [0, 1.49, 0.52], [0.1, 1.53, 0.47]], 0.018);
    if (figure.id === "amodei") {
      const beard = material("#55413b", { roughness: 0.92 });
      ball(root, beard, [0, 1.42, 0.35], [0.38, 0.31, 0.18]);
      ball(root, face, [0, 1.53, 0.49], [0.14, 0.09, 0.07], 14);
      const glasses = material("#243640", { metalness: 0.65, roughness: 0.28 });
      [-0.2, 0.2].forEach((x) => {
        const ring = mesh(root, new THREE.TorusGeometry(0.12, 0.025, 8, 20), glasses, [x, 1.79, 0.49]);
        ring.scale.set(1.2, 0.76, 1);
      });
      line(root, glasses, [[-0.06, 1.79, 0.49], [0.06, 1.79, 0.49]], 0.02);
    }
    if (figure.id === "huang") {
      const chip = material("#8cd84c", { emissive: "#4eaa2d", emissiveIntensity: 0.35, metalness: 0.25 });
      roundedBox(root, chip, [0, 0.74, 0.4], [0.22, 0.22, 0.06], 0.04);
      [-1, 1].forEach((side) => {
        for (let index = 0; index < 3; index += 1) {
          line(root, chip, [[side * 0.13, 0.68 + index * 0.055, 0.4], [side * 0.2, 0.68 + index * 0.055, 0.4]], 0.012);
        }
      });
    }
    if (figure.id === "musk") {
      const rocket = new THREE.Group();
      cylinder(rocket, material("#e4e8ec", { metalness: 0.48, roughness: 0.28 }), [0, 0.14, 0], 0.09, 0.13, 0.44, 12);
      cone(rocket, material("#db554b", { metalness: 0.18 }), [0, 0.43, 0], 0.1, 0.2);
      cone(rocket, material("#df7257"), [-0.1, 0.01, 0], 0.07, 0.2, Math.PI / 2);
      cone(rocket, material("#df7257"), [0.1, 0.01, 0], 0.07, 0.2, -Math.PI / 2);
      rocket.position.set(0.69, 1.05, 0.03);
      rocket.rotation.z = -0.26;
      root.add(rocket);
    }
    arms.push(addArm(root, jacket, -0.49, -1, true), addArm(root, jacket, 0.49, 1, true));
    roundedBox(root, material("#222b33"), [-0.24, 0.17, 0], [0.36, 0.32, 0.42], 0.09);
    roundedBox(root, material("#222b33"), [0.24, 0.17, 0], [0.36, 0.32, 0.42], 0.09);
  }

  const shadow = mesh(
    root,
    new THREE.CircleGeometry(0.64, 32),
    new THREE.MeshBasicMaterial({ color: "#020708", transparent: true, opacity: 0.42, depthWrite: false }),
    [0, 0.025, 0],
    [1, 0.62, 1]
  );
  shadow.rotation.x = -Math.PI / 2;
  shadow.castShadow = false;
  shadow.receiveShadow = false;
  const label = addNameSprite(root, figure.name, figure.color);
  root.userData.arms = arms;
  root.userData.label = label;
  root.userData.phase = Math.random() * Math.PI * 2;
  return root;
}

function skinMaterial(face) {
  return face;
}

function createGridTexture() {
  const canvas = document.createElement("canvas");
  canvas.width = 512;
  canvas.height = 512;
  const context = canvas.getContext("2d");
  context.fillStyle = "#182123";
  context.fillRect(0, 0, 512, 512);
  context.strokeStyle = "rgba(122, 164, 165, .18)";
  context.lineWidth = 2;
  for (let step = 0; step <= 512; step += 64) {
    context.beginPath();
    context.moveTo(step, 0);
    context.lineTo(step, 512);
    context.moveTo(0, step);
    context.lineTo(512, step);
    context.stroke();
  }
  context.strokeStyle = "rgba(145, 193, 188, .22)";
  context.lineWidth = 4;
  for (let step = 0; step <= 512; step += 256) {
    context.beginPath();
    context.moveTo(step, 0);
    context.lineTo(step, 512);
    context.moveTo(0, step);
    context.lineTo(512, step);
    context.stroke();
  }
  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.wrapS = THREE.RepeatWrapping;
  texture.wrapT = THREE.RepeatWrapping;
  texture.repeat.set(2.4, 1.8);
  return texture;
}

function addLabPanel(parent, position, size, metal, trim, glass) {
  roundedBox(parent, metal, position, size, 0.14);
  const [width, height, depth] = size;
  const frontZ = position[2] + depth / 2 + 0.025;
  roundedBox(
    parent,
    glass,
    [position[0], position[1] + height * 0.13, frontZ],
    [width * 0.76, height * 0.46, 0.035],
    0.05
  );
  for (let index = 0; index < 3; index += 1) {
    ball(parent, trim, [position[0] - width * 0.28 + index * 0.11, position[1] - height * 0.36, frontZ + 0.03], [0.035, 0.035, 0.035], 10);
  }
}

function buildLaboratory(scene) {
  const metal = material("#364144", { metalness: 0.72, roughness: 0.38 });
  const darkMetal = material("#151d20", { metalness: 0.58, roughness: 0.46 });
  const trim = material("#a9c0ba", { metalness: 0.5, roughness: 0.32 });
  const glass = material("#4c7475", { metalness: 0.32, roughness: 0.19, transparent: true, opacity: 0.58 });
  const tealLight = material("#80e0c2", { emissive: "#68daba", emissiveIntensity: 2.1, roughness: 0.25 });

  mesh(scene, new THREE.BoxGeometry(ROOM.width, 0.42, ROOM.depth), darkMetal, [0, -0.25, 0]);
  mesh(
    scene,
    new THREE.PlaneGeometry(ROOM.width - 0.7, ROOM.depth - 0.7),
    new THREE.MeshStandardMaterial({ map: createGridTexture(), roughness: 0.86, metalness: 0.18 }),
    [0, -0.025, 0]
  ).rotation.x = -Math.PI / 2;

  const wallSurface = material("#202b2e", { metalness: 0.45, roughness: 0.58 });
  const wallGlass = material("#45676a", { metalness: 0.25, roughness: 0.2, transparent: true, opacity: 0.22, side: THREE.DoubleSide });
  // Back wall modules leave the center glazing clear so the room reads as a model lab.
  for (let x = -15; x <= 15; x += 5) {
    roundedBox(scene, wallSurface, [x, 3.9, -12.8], [4.8, 7.8, 0.42], 0.2);
    roundedBox(scene, wallGlass, [x, 5.25, -12.56], [4.16, 3.5, 0.08], 0.1);
    roundedBox(scene, trim, [x, 1.4, -12.52], [4.16, 0.12, 0.08], 0.025);
  }
  // Side walls use separated glass panels; the orbit camera can still see into the lab.
  for (const side of [-1, 1]) {
    roundedBox(scene, wallSurface, [side * 17.8, 3.75, 0], [0.45, 7.5, ROOM.depth], 0.14);
    for (let z = -8; z <= 8; z += 5.3) {
      roundedBox(scene, wallGlass, [side * 17.54, 5.25, z], [0.08, 3.2, 4.2], 0.06);
      roundedBox(scene, trim, [side * 17.49, 1.15, z], [0.09, 0.11, 4.6], 0.025);
    }
  }
  // A split entry rail marks the open front of the miniature lab.
  for (const side of [-1, 1]) {
    roundedBox(scene, metal, [side * 13.5, 1.55, 12.7], [8.6, 3.1, 0.5], 0.14);
    roundedBox(scene, glass, [side * 13.5, 2.05, 12.42], [7.5, 1.8, 0.06], 0.08);
  }

  // Ceiling gantry and cool task lights.
  for (let x = -11; x <= 11; x += 5.5) {
    cylinder(scene, darkMetal, [x, 8.2, -1], 0.075, 0.075, 17, 12).rotation.x = Math.PI / 2;
  }
  for (let z = -8; z <= 8; z += 5.2) {
    roundedBox(scene, metal, [0, 8.45, z], [27, 0.28, 0.36], 0.08);
    roundedBox(scene, tealLight, [0, 8.26, z], [22, 0.055, 0.12], 0.02);
    const light = new THREE.PointLight(0x9debd6, 38, 18, 1.8);
    light.position.set(0, 7.6, z);
    scene.add(light);
  }

  // Workbenches, tool cabinets and signal rails along the room walls.
  for (const side of [-1, 1]) {
    roundedBox(scene, darkMetal, [side * 12.7, 0.93, -1.2], [5.8, 1.8, 3.4], 0.16);
    roundedBox(scene, metal, [side * 12.7, 1.93, -1.2], [6.3, 0.24, 4.0], 0.08);
    for (let index = 0; index < 3; index += 1) {
      addLabPanel(scene, [side * (10.9 + index * 1.8), 3.5, -10.9], [1.48, 2.3, 0.55], metal, tealLight, glass);
    }
    for (let index = 0; index < 7; index += 1) {
      const pipeZ = -8.8 + index * 2.1;
      cylinder(scene, trim, [side * 16.0, 3.15, pipeZ], 0.055, 0.055, 1.8, 10).rotation.x = Math.PI / 2;
    }
  }

  // Rear glass cabinets and industrial pillars.
  for (let x = -14; x <= 14; x += 7) {
    roundedBox(scene, darkMetal, [x, 2.65, -11.65], [0.35, 5.1, 0.45], 0.1);
    roundedBox(scene, trim, [x, 5.25, -11.36], [0.62, 0.08, 0.08], 0.025);
  }
  for (let x = -15; x <= 15; x += 3.75) {
    roundedBox(scene, metal, [x, 0.015, 11.4], [0.12, 0.04, 1.2], 0.015);
  }

  const floorLamp = new THREE.DirectionalLight(0xc4e8dc, 2.6);
  floorLamp.position.set(-7, 15, 10);
  floorLamp.castShadow = true;
  floorLamp.shadow.mapSize.set(1536, 1536);
  floorLamp.shadow.camera.left = -22;
  floorLamp.shadow.camera.right = 22;
  floorLamp.shadow.camera.top = 20;
  floorLamp.shadow.camera.bottom = -20;
  floorLamp.shadow.bias = -0.00035;
  scene.add(floorLamp);
  scene.add(new THREE.HemisphereLight(0xb7ded5, 0x11181c, 2.0));
  const warmFill = new THREE.PointLight(0xd59756, 16, 30, 2);
  warmFill.position.set(8, 5, 8);
  scene.add(warmFill);

  const stopRig = new THREE.Group();
  stopRig.position.set(STOP_POINT.x, 0, STOP_POINT.z);
  scene.add(stopRig);
  roundedBox(stopRig, darkMetal, [0, 0.67, 0], [2.2, 1.3, 1.8], 0.16);
  roundedBox(stopRig, material("#465354", { metalness: 0.6, roughness: 0.32 }), [0, 1.36, 0], [2.3, 0.14, 1.9], 0.04);
  const button = cylinder(stopRig, material("#d73932", { roughness: 0.28, metalness: 0.12, emissive: "#8d1713", emissiveIntensity: 0.32 }), [0.12, 1.72, 0.05], 0.5, 0.56, 0.48, 32);
  button.userData.hitType = "stop";
  button.userData.hitId = "stop";
  const stopCaption = createCanvasLabel("WE NEED TO STOP", "#ff8a73", "#241414", 512, 112);
  const stopSign = new THREE.Mesh(
    new THREE.PlaneGeometry(1.65, 0.36),
    new THREE.MeshBasicMaterial({ map: stopCaption.texture, transparent: true, side: THREE.DoubleSide })
  );
  stopSign.position.set(0, 1.22, 0.94);
  stopRig.add(stopSign);
  stopRig.userData.button = button;
  stopRig.userData.caption = stopCaption;
  stopRig.userData.state = "ready";

  return stopRig;
}

function createCanvasLabel(text, foreground, background, width = 512, height = 128) {
  const canvas = document.createElement("canvas");
  canvas.width = width;
  canvas.height = height;
  const context = canvas.getContext("2d");
  drawCanvasLabel({ canvas, context }, text, foreground, background);
  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  return { canvas, context, texture };
}

function drawCanvasLabel(label, text, foreground, background) {
  const { canvas, context } = label;
  context.clearRect(0, 0, canvas.width, canvas.height);
  context.fillStyle = background;
  context.beginPath();
  context.roundRect(2, 2, canvas.width - 4, canvas.height - 4, 20);
  context.fill();
  context.strokeStyle = `${foreground}88`;
  context.lineWidth = 4;
  context.stroke();
  context.fillStyle = foreground;
  context.font = "700 46px Arial, sans-serif";
  context.textAlign = "center";
  context.textBaseline = "middle";
  context.fillText(text, canvas.width / 2, canvas.height / 2, canvas.width - 30);
}

function drawRepoFace(canvas, project) {
  const context = canvas.getContext("2d");
  context.clearRect(0, 0, canvas.width, canvas.height);
  context.fillStyle = project.dead ? "#c9b9a4" : "#eee5d4";
  context.fillRect(0, 0, canvas.width, canvas.height);
  context.fillStyle = "#d4c6ad";
  context.fillRect(0, 0, canvas.width, 28);
  context.fillStyle = "#a4732b";
  context.beginPath();
  context.roundRect(28, 54, 42, 31, 6);
  context.fill();
  context.fillStyle = "#eee5d4";
  context.fillRect(28, 49, 22, 13);
  context.fillStyle = "#897552";
  context.font = "700 20px Arial, sans-serif";
  context.fillText("REPO", 86, 78);
  context.textAlign = "right";
  context.fillText(`★ ${project.repo.stars || 0}`, 480, 78);
  context.textAlign = "left";
  context.fillStyle = "#191b1a";
  context.font = "700 35px Arial, sans-serif";
  const name = String(project.repo.name || "repo");
  let shownName = name;
  while (context.measureText(shownName).width > 454 && shownName.length > 8) {
    shownName = `${shownName.slice(0, -4)}…`;
  }
  context.fillText(shownName, 28, 143);
  context.fillStyle = "#a7782a";
  context.beginPath();
  context.arc(36, 190, 8, 0, Math.PI * 2);
  context.fill();
  context.fillStyle = "#6b5e49";
  context.font = "600 23px Arial, sans-serif";
  context.fillText(project.repo.lang || "Dil belirtilmemiş", 56, 198, 256);
  const damage = project.damage || 0;
  for (let index = 0; index < 3; index += 1) {
    context.fillStyle = index < damage ? "#cf5e43" : "#c6b797";
    context.fillRect(374 + index * 31, 188, 22, 9);
  }
  if (damage > 0) {
    context.strokeStyle = "rgba(125, 40, 28, .64)";
    context.lineWidth = 4;
    context.beginPath();
    context.moveTo(258, 21);
    context.lineTo(272, 91);
    context.lineTo(242, 130);
    context.lineTo(299, 205);
    context.moveTo(270, 92);
    context.lineTo(335, 63);
    context.stroke();
  }
  context.strokeStyle = "rgba(103, 74, 34, .25)";
  context.lineWidth = 3;
  context.strokeRect(2, 2, canvas.width - 4, canvas.height - 4);
}

function makeProjectCard(project) {
  const group = new THREE.Group();
  const cardMaterial = material("#e8deca", { roughness: 0.72, metalness: 0.06 });
  const backing = mesh(group, new THREE.BoxGeometry(2.48, 0.15, 1.54), cardMaterial, [0, 0.12, 0]);
  backing.userData.hitType = "project";
  backing.userData.hitId = project.key;
  const canvas = document.createElement("canvas");
  canvas.width = 512;
  canvas.height = 256;
  drawRepoFace(canvas, project);
  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  const face = mesh(
    group,
    new THREE.PlaneGeometry(2.36, 1.4),
    new THREE.MeshStandardMaterial({ map: texture, roughness: 0.82, metalness: 0.02, side: THREE.DoubleSide }),
    [0, 0.202, 0]
  );
  face.rotation.x = -Math.PI / 2;
  face.userData.hitType = "project";
  face.userData.hitId = project.key;
  for (const x of [-1.03, 1.03]) {
    cylinder(group, material("#bb9a61", { metalness: 0.55, roughness: 0.4 }), [x, 0.23, -0.56], 0.055, 0.055, 0.1, 12);
    cylinder(group, material("#bb9a61", { metalness: 0.55, roughness: 0.4 }), [x, 0.23, 0.56], 0.055, 0.055, 0.1, 12);
  }
  group.userData.hitType = "project";
  group.userData.hitId = project.key;
  group.userData.canvas = canvas;
  group.userData.texture = texture;
  group.userData.breaking = false;
  return group;
}

function splitText(context, text, maxWidth) {
  const words = String(text || "").split(/\s+/);
  const lines = [];
  let lineText = "";
  words.forEach((word) => {
    const candidate = lineText ? `${lineText} ${word}` : word;
    if (lineText && context.measureText(candidate).width > maxWidth) {
      lines.push(lineText);
      lineText = word;
    } else {
      lineText = candidate;
    }
  });
  if (lineText) lines.push(lineText);
  return lines;
}

function drawBubbleTexture(canvas, figure, bubble) {
  const context = canvas.getContext("2d");
  context.clearRect(0, 0, canvas.width, canvas.height);
  context.fillStyle = "#f3ecdd";
  context.beginPath();
  context.roundRect(7, 7, canvas.width - 14, canvas.height - 14, 28);
  context.fill();
  context.strokeStyle = figure.color;
  context.lineWidth = 7;
  context.beginPath();
  context.roundRect(8, 8, canvas.width - 16, canvas.height - 16, 28);
  context.stroke();
  context.fillStyle = figure.color;
  context.beginPath();
  context.arc(42, 42, 10, 0, Math.PI * 2);
  context.fill();
  context.textAlign = "left";
  context.fillStyle = "#172321";
  context.font = "700 30px Arial, sans-serif";
  context.fillText(`${figure.name} · ${figure.vendor}`, 66, 52, canvas.width - 100);
  context.strokeStyle = "rgba(23, 35, 33, .22)";
  context.lineWidth = 2;
  context.beginPath();
  context.moveTo(30, 72);
  context.lineTo(canvas.width - 30, 72);
  context.stroke();
  context.fillStyle = "#202522";
  context.font = "500 32px Arial, sans-serif";
  const lines = splitText(context, bubble.text, canvas.width - 54).slice(0, 4);
  lines.forEach((lineText, index) => {
    context.fillText(lineText, 30, 116 + index * 38, canvas.width - 56);
  });
  const footer = bubble.targetName
    ? `→ ${bubble.targetName}`
    : bubble.repoName
    ? `HEDEF: ${bubble.repoName}`
    : "";
  if (footer) {
    context.fillStyle = "#555346";
    context.font = "700 19px Arial, sans-serif";
    context.fillText(footer.toUpperCase(), 30, canvas.height - 18, canvas.width - 60);
  }
}

function makeBubbleSprite(figure, bubble) {
  const canvas = document.createElement("canvas");
  canvas.width = 640;
  canvas.height = 280;
  drawBubbleTexture(canvas, figure, bubble);
  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  const sprite = new THREE.Sprite(
    new THREE.SpriteMaterial({
      map: texture,
      transparent: true,
      depthWrite: false,
      depthTest: false,
      toneMapped: false,
      opacity: 1,
    })
  );
  sprite.scale.set(8.2, 3.59, 1);
  sprite.position.set(0, 4.1, 0);
  sprite.userData.canvas = canvas;
  sprite.userData.texture = texture;
  sprite.userData.contentKey = "";
  return sprite;
}

function worldWidthFor(dims) {
  const aspect = dims.w / Math.max(1, dims.h);
  return Math.min(ROOM.width - 4, Math.max(18, (ROOM.depth - 4) * aspect));
}

function mapToWorld(x, y, dims) {
  return new THREE.Vector3(
    ((x / Math.max(1, dims.w)) - 0.5) * worldWidthFor(dims),
    0,
    ((y / Math.max(1, dims.h)) - 0.5) * (ROOM.depth - 4)
  );
}

function disposeTree(root) {
  root.traverse((object) => {
    if (object.geometry) object.geometry.dispose();
    if (object.material) {
      const materials = Array.isArray(object.material) ? object.material : [object.material];
      materials.forEach((surface) => {
        if (surface.map) surface.map.dispose();
        surface.dispose();
      });
    }
  });
}

function drawDebris(scene, card, debris) {
  const origin = card.position.clone();
  for (let index = 0; index < 11; index += 1) {
    const geometry = index % 3 === 0
      ? new THREE.TetrahedronGeometry(0.22 + Math.random() * 0.12)
      : new THREE.BoxGeometry(0.22 + Math.random() * 0.22, 0.08, 0.16 + Math.random() * 0.12);
    const piece = new THREE.Mesh(
      geometry,
      material(index % 4 === 0 ? "#dc9d69" : "#e9dfcd", { roughness: 0.72 })
    );
    piece.position.set(
      origin.x + (Math.random() - 0.5) * 1.6,
      origin.y + 0.25 + Math.random() * 0.3,
      origin.z + (Math.random() - 0.5) * 1.2
    );
    piece.castShadow = true;
    scene.add(piece);
    debris.push({
      object: piece,
      vx: (Math.random() - 0.5) * 4.6,
      vy: 1.7 + Math.random() * 3.2,
      vz: (Math.random() - 0.5) * 4.6,
      rx: (Math.random() - 0.5) * 8,
      ry: (Math.random() - 0.5) * 8,
      life: 1.15 + Math.random() * 0.7,
    });
  }
}

function updateCard(card, project, dims) {
  const point = mapToWorld(project.x, project.y, dims);
  card.position.set(point.x, 0.035, point.z);
  card.rotation.y = ((project.rot || 0) * Math.PI) / 180;
  const revision = `${project.repo.name}-${project.repo.stars}-${project.repo.lang}-${project.damage}-${project.dead}`;
  if (card.userData.revision !== revision) {
    drawRepoFace(card.userData.canvas, project);
    card.userData.texture.needsUpdate = true;
    card.userData.revision = revision;
  }
}

export default function LaboratoryScene3D({
  sceneRef,
  projects,
  bubbles,
  stopState,
  reduced,
  onFigureClick,
  onProjectClick,
  onStopClick,
}) {
  const mountRef = useRef(null);
  const callbacksRef = useRef({ onFigureClick, onProjectClick, onStopClick });
  const [failed, setFailed] = React.useState(false);

  callbacksRef.current = { onFigureClick, onProjectClick, onStopClick };

  useEffect(() => {
    const mount = mountRef.current;
    if (!mount) return undefined;

    let renderer;
    try {
      renderer = new THREE.WebGLRenderer({ alpha: false, antialias: true, powerPreference: "high-performance" });
    } catch {
      setFailed(true);
      return undefined;
    }

    setFailed(false);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.65));
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.2;
    renderer.domElement.className = "scene3d-canvas";
    renderer.domElement.setAttribute("aria-label", "Döndürülebilir üç boyutlu yapay zekâ laboratuvarı. Fareyle veya dokunarak döndür.");
    renderer.domElement.setAttribute("role", "img");
    renderer.domElement.tabIndex = 0;
    mount.appendChild(renderer.domElement);

    const scene = new THREE.Scene();
    scene.background = new THREE.Color("#11191b");
    scene.fog = new THREE.FogExp2("#11191b", 0.0095);
    const camera = new THREE.PerspectiveCamera(42, 1, 0.1, 160);
    camera.position.copy(CAMERA_HOME);
    const controls = new OrbitControls(camera, renderer.domElement);
    controls.target.copy(CAMERA_TARGET);
    controls.enableDamping = true;
    controls.dampingFactor = 0.075;
    controls.enablePan = false;
    controls.rotateSpeed = 0.62;
    controls.minDistance = 9;
    controls.maxDistance = 34;
    controls.minPolarAngle = 0.12;
    controls.maxPolarAngle = 1.55;
    controls.update();

    const stopRig = buildLaboratory(scene);
    const figures = new Map();
    const cards = new Map();
    const debris = [];
    const raycaster = new THREE.Raycaster();
    const pointer = new THREE.Vector2();
    let pointerStart = null;
    let frame = 0;
    let previousTime = performance.now();
    let scenePaused = false;
    const time = new THREE.Clock();

    FIGURES.forEach((figure) => {
      const object = makeModel(figure);
      object.userData.hitType = "figure";
      object.userData.hitId = figure.id;
      scene.add(object);
      figures.set(figure.id, object);
    });

    const resize = () => {
      const width = Math.max(1, mount.clientWidth);
      const height = Math.max(1, mount.clientHeight);
      renderer.setSize(width, height, false);
      camera.aspect = width / height;
      camera.updateProjectionMatrix();
    };
    resize();
    const observer = typeof ResizeObserver !== "undefined" ? new ResizeObserver(resize) : null;
    if (observer) observer.observe(mount);
    window.addEventListener("resize", resize);

    const findHit = (event) => {
      const rect = renderer.domElement.getBoundingClientRect();
      pointer.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
      pointer.y = -((event.clientY - rect.top) / rect.height) * 2 + 1;
      raycaster.setFromCamera(pointer, camera);
      const intersections = raycaster.intersectObjects(scene.children, true);
      for (const intersection of intersections) {
        let object = intersection.object;
        while (object && !object.userData.hitType) object = object.parent;
        if (object && object.userData.hitType) return object;
      }
      return null;
    };

    const onPointerDown = (event) => {
      if (event.button !== undefined && event.button !== 0) return;
      pointerStart = { x: event.clientX, y: event.clientY, id: event.pointerId };
    };
    const onPointerUp = (event) => {
      if (!pointerStart || pointerStart.id !== event.pointerId) return;
      const distance = Math.hypot(event.clientX - pointerStart.x, event.clientY - pointerStart.y);
      pointerStart = null;
      if (distance > 5) return;
      const hit = findHit(event);
      if (!hit) return;
      if (hit.userData.hitType === "figure") callbacksRef.current.onFigureClick(hit.userData.hitId);
      if (hit.userData.hitType === "project") callbacksRef.current.onProjectClick(hit.userData.hitId);
      if (hit.userData.hitType === "stop") callbacksRef.current.onStopClick();
    };
    const onPointerMove = (event) => {
      const hit = findHit(event);
      renderer.domElement.style.cursor = hit ? "pointer" : "grab";
    };
    renderer.domElement.addEventListener("pointerdown", onPointerDown);
    renderer.domElement.addEventListener("pointerup", onPointerUp);
    renderer.domElement.addEventListener("pointermove", onPointerMove);

    const api = {
      updatePose(figureNodes, projectNodes, dims, paused, now) {
        scenePaused = paused || reduced;
        const currentTime = now / 1000;
        stopRig.position.x = Math.min(STOP_POINT.x, worldWidthFor(dims) / 2 - 2.2);
        FIGURES.forEach((figure) => {
          const node = figureNodes[figure.id];
          const object = figures.get(figure.id);
          if (!node || !object) return;
          const point = mapToWorld(node.x, node.y, dims);
          object.position.x = point.x;
          object.position.z = point.z;
          const scale = Math.max(0.68, Math.min(1.24, node.size / 76));
          object.scale.setScalar(scale);
          const speed = Math.hypot(node.vx, node.vy);
          if (speed > 2) object.rotation.y = Math.atan2(node.vx, node.vy);
          object.userData.velocity = speed;
          object.userData.phase = node.motionPhase || 0;
          object.userData.bobTime = currentTime;
          object.userData.mode = node.mode;
          object.userData.specialTarget = Boolean(node.specialTarget);
        });
        projectNodes.forEach((project) => {
          const card = cards.get(project.key);
          if (card) updateCard(card, project, dims);
        });
      },
      syncProjects(nextProjects, dims) {
        const active = new Set(nextProjects.map((project) => project.key));
        nextProjects.forEach((project) => {
          let card = cards.get(project.key);
          if (!card) {
            card = makeProjectCard(project);
            cards.set(project.key, card);
            scene.add(card);
          }
          if (project.dead) {
            if (!card.userData.breaking) {
              card.userData.breaking = true;
              drawDebris(scene, card, debris);
              card.visible = false;
              card.traverse((part) => {
                delete part.userData.hitType;
                delete part.userData.hitId;
              });
            }
          } else {
            updateCard(card, project, dims);
          }
        });
        cards.forEach((card, key) => {
          if (!active.has(key)) {
            scene.remove(card);
            disposeTree(card);
            cards.delete(key);
          }
        });
      },
      syncBubbles(nextBubbles) {
        FIGURES.forEach((figure) => {
          const object = figures.get(figure.id);
          if (!object) return;
          const bubble = nextBubbles[figure.id];
          let sprite = object.userData.bubble;
          if (!bubble) {
            if (sprite) {
              object.remove(sprite);
              sprite.material.map.dispose();
              sprite.material.dispose();
              object.userData.bubble = null;
            }
            object.userData.label.visible = true;
            return;
          }
          if (!sprite) {
            sprite = makeBubbleSprite(figure, bubble);
            object.add(sprite);
            object.userData.bubble = sprite;
          }
          const contentKey = `${bubble.text}|${bubble.repoName || ""}|${bubble.targetName || ""}`;
          if (sprite.userData.contentKey !== contentKey) {
            drawBubbleTexture(sprite.userData.canvas, figure, bubble);
            sprite.userData.texture.needsUpdate = true;
            sprite.userData.contentKey = contentKey;
          }
          object.userData.label.visible = false;
          sprite.position.y = 4.1 + (bubble.below ? -1.35 : 0);
        });
      },
      triggerFigure(id, action) {
        const object = figures.get(id);
        if (object) {
          object.userData.action = action;
          object.userData.actionUntil = performance.now() + (action === "audit" ? 1400 : 850);
        }
      },
      triggerProject(key) {
        const card = cards.get(key);
        if (card) {
          card.userData.hitAt = performance.now();
          card.userData.hitOriginalY = card.position.y;
        }
      },
      triggerStop() {
        stopRig.userData.pressedUntil = performance.now() + 540;
      },
      setStopState(state) {
        if (stopRig.userData.state === state) return;
        stopRig.userData.state = state;
        const text = state === "approaching"
          ? "SAM YOLA ÇIKTI"
          : state === "pressed"
          ? "BASILDI — HERHALDE"
          : "WE NEED TO STOP";
        drawCanvasLabel(stopRig.userData.caption, text, "#ff8a73", "#241414");
        stopRig.userData.caption.texture.needsUpdate = true;
      },
      getStopPoint(width, height) {
        const worldWidth = worldWidthFor({ w: width, h: height });
        const stopX = Math.min(STOP_POINT.x, worldWidth / 2 - 2.2);
        return {
          x: ((stopX / worldWidth) + 0.5) * width,
          y: ((STOP_POINT.z / (ROOM.depth - 4)) + 0.5) * height,
        };
      },
      orbit(yaw, pitch) {
        const offset = camera.position.clone().sub(controls.target);
        const spherical = new THREE.Spherical().setFromVector3(offset);
        spherical.theta -= yaw;
        spherical.phi = THREE.MathUtils.clamp(spherical.phi + pitch, 0.12, 1.55);
        offset.setFromSpherical(spherical);
        camera.position.copy(controls.target).add(offset);
        controls.update();
      },
      resetCamera() {
        camera.position.copy(CAMERA_HOME);
        controls.target.copy(CAMERA_TARGET);
        controls.update();
      },
    };
    sceneRef.current = api;

    const animate = (now) => {
      const dt = Math.min(0.05, (now - previousTime) / 1000);
      previousTime = now;
      const elapsed = time.getElapsedTime();
      figures.forEach((object) => {
        const phase = object.userData.phase || 0;
        const movement = object.userData.velocity || 0;
        if (!scenePaused) {
          object.position.y = Math.sin(elapsed * 2.7 + phase) * (movement > 5 ? 0.055 : 0.025);
          object.userData.arms.forEach((arm, index) => {
            arm.rotation.z = Math.sin(elapsed * (movement > 5 ? 8 : 2.3) + phase + index * Math.PI) * (movement > 5 ? 0.32 : 0.07);
          });
        }
        const action = object.userData.action;
        const actionLeft = (object.userData.actionUntil - now) / 850;
        if (action && actionLeft > 0) {
          const pulse = Math.sin((1 - actionLeft) * Math.PI * 5);
          if (action === "charge") object.scale.y = Math.max(0.68, object.scale.x * (1 + Math.max(0, pulse) * 0.12));
          if (action === "smash") object.rotation.z = pulse * 0.22;
          if (action === "press") object.rotation.x = Math.max(0, pulse) * 0.28;
          if (action === "audit") object.userData.arms[0].rotation.z = -0.8 + pulse * 0.15;
        } else {
          object.userData.action = null;
          object.rotation.x = 0;
          object.rotation.z = 0;
          object.scale.y = object.scale.x;
        }
      });

      cards.forEach((card) => {
        if (card.userData.hitAt && now - card.userData.hitAt < 280) {
          const elapsedHit = now - card.userData.hitAt;
          card.position.y = card.userData.hitOriginalY + Math.sin((elapsedHit / 280) * Math.PI * 3) * 0.11 * (1 - elapsedHit / 280);
          card.rotation.z = Math.sin((elapsedHit / 280) * Math.PI * 3) * 0.055;
        } else {
          card.userData.hitAt = 0;
          card.rotation.z = 0;
        }
      });

      if (stopRig.userData.pressedUntil > now) {
        stopRig.userData.button.position.y = 1.5;
      } else {
        stopRig.userData.button.position.y = 1.72;
      }

      for (let index = debris.length - 1; index >= 0; index -= 1) {
        const piece = debris[index];
        piece.life -= dt;
        piece.vy -= 8.5 * dt;
        piece.object.position.x += piece.vx * dt;
        piece.object.position.y += piece.vy * dt;
        piece.object.position.z += piece.vz * dt;
        piece.object.rotation.x += piece.rx * dt;
        piece.object.rotation.y += piece.ry * dt;
        if (piece.life <= 0) {
          scene.remove(piece.object);
          disposeTree(piece.object);
          debris.splice(index, 1);
        }
      }

      controls.update();
      renderer.render(scene, camera);
      frame = window.requestAnimationFrame(animate);
    };
    frame = window.requestAnimationFrame(animate);

    return () => {
      window.cancelAnimationFrame(frame);
      if (observer) observer.disconnect();
      window.removeEventListener("resize", resize);
      renderer.domElement.removeEventListener("pointerdown", onPointerDown);
      renderer.domElement.removeEventListener("pointerup", onPointerUp);
      renderer.domElement.removeEventListener("pointermove", onPointerMove);
      controls.dispose();
      sceneRef.current = null;
      disposeTree(scene);
      renderer.dispose();
      if (renderer.domElement.parentNode === mount) mount.removeChild(renderer.domElement);
    };
  }, [sceneRef, reduced]);

  useEffect(() => {
    if (sceneRef.current) {
      sceneRef.current.syncProjects(projects, { w: mountRef.current?.clientWidth || 1, h: mountRef.current?.clientHeight || 1 });
    }
  }, [projects, sceneRef]);

  useEffect(() => {
    if (sceneRef.current) sceneRef.current.syncBubbles(bubbles);
  }, [bubbles, sceneRef]);

  useEffect(() => {
    if (sceneRef.current) sceneRef.current.setStopState(stopState);
  }, [sceneRef, stopState]);

  return (
    <div className="scene3d-host" ref={mountRef}>
      {failed && (
        <div className="scene3d-error" role="status">
          Bu tarayıcı 3B sahneyi açamadı. WebGL desteğini denetleyip sayfayı yenile.
        </div>
      )}
    </div>
  );
}


