import React, {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import DeliveryEngine from "./DeliveryEngine";
import LaboratoryScene3D from "./LaboratoryScene3D";
import {
  FIGURES,
  FIGURE_BY_ID,
  SITE_KICKER,
} from "./figures";
import { SHOUTS } from "./lines";
import { QUESTIONS } from "./questions";
import REPOS from "./repos.json";
import { countClick } from "./clickCounter";
import "./arena.css";

const MAX_DAMAGE = 3;
const BUBBLE_LIMIT = { wide: 3, narrow: 1 };

const clamp = (value, min, max) => Math.min(Math.max(value, min), max);
const randomBetween = (min, max) => min + Math.random() * (max - min);

function steerNode(node, targetX, targetY, speed, dt, now, motion = {}, burst = 1) {
  const dx = targetX - node.x;
  const dy = targetY - node.y;
  const distance = Math.hypot(dx, dy) || 1;
  const easedSpeed = Math.min(speed * burst, distance * 2.5);
  const drift = (motion.drift || 0) * Math.sin(now / 520 + node.motionPhase) *
    clamp(distance / 100, 0, 1);
  const desiredX = (dx / distance) * easedSpeed - (dy / distance) * drift;
  const desiredY = (dy / distance) * easedSpeed + (dx / distance) * drift;
  const response = 1 - Math.exp(-(motion.turn || 2.2) * dt);

  node.vx += (desiredX - node.vx) * response;
  node.vy += (desiredY - node.vy) * response;
  node.x += node.vx * dt;
  node.y += node.vy * dt;
  return distance;
}

function cardSize(width) {
  if (width < 520) return { w: 104, h: 68 };
  if (width < 900) return { w: 128, h: 82 };
  return { w: 154, h: 96 };
}

function figureSize(width) {
  if (width < 520) return 56;
  if (width < 900) return 76;
  return 94;
}

function projectSlots(width, count) {
  if (count <= 2) {
    return [
      [0.28, 0.36],
      [0.72, 0.68],
    ];
  }
  return [
    [0.22, 0.32],
    [0.52, 0.22],
    [0.79, 0.4],
    [0.46, 0.72],
  ].slice(0, count);
}

function Arena() {
  const [paused, setPaused] = useState(false);
  const [chaos, setChaos] = useState(false);
  const [projects, setProjects] = useState([]);
  const [bubbles, setBubbles] = useState({});
  const [log, setLog] = useState([]);
  const [brokenCount, setBrokenCount] = useState(0);
  const [lastDestroyed, setLastDestroyed] = useState(null);
  const [aboutOpen, setAboutOpen] = useState(false);
  const [logOpen, setLogOpen] = useState(false);
  const [questionFigureId, setQuestionFigureId] = useState(null);
  const [selectedQuestionId, setSelectedQuestionId] = useState(null);
  const [stopButtonState, setStopButtonState] = useState("ready");

  const reduced = useMemo(() => {
    if (typeof window === "undefined" || !window.matchMedia) return false;
    return window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  }, []);

  const stageRef = useRef(null);
  const sceneApiRef = useRef(null);
  const simRef = useRef(null);
  const engineRef = useRef(null);
  const bubbleTimers = useRef([]);
  const pageViewCounted = useRef(false);

  if (!engineRef.current) engineRef.current = new DeliveryEngine();

  if (!simRef.current) {
    simRef.current = {
      dims: { w: 0, h: 0 },
      figures: {},
      projects: [],
      projectSeq: 0,
      brokenCount: 0,
      paused: false,
      chaos: false,
      bubbleTimers: [],
    };
  }

  useEffect(() => {
    simRef.current.paused = paused;
  }, [paused]);

  useEffect(() => {
    if (pageViewCounted.current) return;
    pageViewCounted.current = true;
    countClick("page_view");
  }, []);

  useEffect(() => {
    simRef.current.chaos = chaos;
  }, [chaos]);

  useEffect(
    () => () => {
      bubbleTimers.current.forEach((timer) => window.clearTimeout(timer));
    },
    []
  );

  const syncProjects = useCallback(() => {
    setProjects(simRef.current.projects.map((project) => ({ ...project })));
  }, []);

  /** Balonun yerini sahne içinde güvenli bir noktaya oturtur. */
  const announce = useCallback((figureId, payload) => {
    const sim = simRef.current;
    const figure = sim.figures[figureId];
    if (!figure || !payload) return;

    const dims = sim.dims;
    const width =
      dims.w < 720
        ? Math.min(252, Math.max(172, dims.w - 28))
        : Math.min(296, Math.max(200, dims.w - 28));

    const id = `${figureId}-${Date.now()}-${Math.random()}`;
    const createdAt = Date.now();
    const duration = Math.min(
      9200,
      Math.max(4200, 3000 + payload.text.length * 44)
    );

    setBubbles((previous) => {
      const approxHeight = clamp(
        60 + Math.ceil(payload.text.length / (width / 6.4)) * 20,
        78,
        200
      );
      const others = Object.values(previous).filter(
        (bubble) => bubble.figureId !== figureId
      );
      const actors = FIGURES.map((def) => sim.figures[def.id])
        .filter(Boolean)
        .filter((node) => node.id !== figureId);
      const cards = sim.projects.filter((project) => !project.dead);

      const candidates = [];

      [true, false].forEach((above) => {
        [-1.6, -0.8, 0, 0.8, 1.6].forEach((shift) => {
          const rawLeft = clamp(
            figure.x - width / 2 + shift * width * 0.5,
            8,
            Math.max(8, dims.w - width - 8)
          );
          const rawTop = above
            ? figure.y - figure.size / 2 - approxHeight - 14
            : figure.y + figure.size / 2 + 14;

          let score = Math.abs(shift) * 26;
          if (rawTop < 8) score += 10000 + (8 - rawTop) * 8;
          if (rawTop + approxHeight > dims.h - 8) {
            score += 10000 + rawTop + approxHeight - (dims.h - 8);
          }

          others.forEach((other) => {
            const overlapX =
              Math.min(rawLeft + width, other.x + other.w) -
              Math.max(rawLeft, other.x);
            const overlapY =
              Math.min(rawTop + approxHeight, other.y + other.h) -
              Math.max(rawTop, other.y);
            if (overlapX > 0 && overlapY > 0) {
              score += overlapX * overlapY * 0.14 + 320;
            }
          });

          actors.forEach((node) => {
            const overlapX =
              Math.min(rawLeft + width, node.x + node.size / 2) -
              Math.max(rawLeft, node.x - node.size / 2);
            const overlapY =
              Math.min(rawTop + approxHeight, node.y + node.size / 2) -
              Math.max(rawTop, node.y - node.size / 2);
            if (overlapX > 0 && overlapY > 0) {
              score += overlapX * overlapY * 0.08;
            }
          });

          cards.forEach((card) => {
            const overlapX =
              Math.min(rawLeft + width, card.x + card.w / 2) -
              Math.max(rawLeft, card.x - card.w / 2);
            const overlapY =
              Math.min(rawTop + approxHeight, card.y + card.h / 2) -
              Math.max(rawTop, card.y - card.h / 2);
            if (overlapX > 0 && overlapY > 0) {
              score += overlapX * overlapY * 0.3 + 600;
            }
          });

          candidates.push({
            x: rawLeft,
            y: rawTop,
            w: width,
            h: approxHeight,
            above,
            score,
          });
        });
      });

      candidates.sort((a, b) => a.score - b.score);
      const spot = candidates[0];

      const next = {
        ...previous,
        [figureId]: {
          id,
          figureId,
          text: payload.text,
          repoName: payload.repoName,
          targetName: payload.targetName,
          x: spot.x,
          y: spot.y,
          w: spot.w,
          h: spot.h,
          left: spot.x - (figure.x - figure.size / 2),
          tail: clamp(figure.x - spot.x, 20, width - 20),
          width,
          below: !spot.above,
          createdAt,
        },
      };

      const limit = dims.w < 720 ? BUBBLE_LIMIT.narrow : BUBBLE_LIMIT.wide;
      const entries = Object.entries(next);
      if (entries.length <= limit) return next;

      return entries
        .sort((a, b) => a[1].createdAt - b[1].createdAt)
        .slice(entries.length - limit)
        .reduce((accumulator, [key, value]) => {
          accumulator[key] = value;
          return accumulator;
        }, {});
    });

    setLog((previous) =>
      [
        {
          id,
          figureId,
          text: payload.text,
          repoName: payload.repoName,
          targetName: payload.targetName,
          time: new Date(),
        },
        ...previous,
      ].slice(0, 90)
    );

    const timer = window.setTimeout(() => {
      setBubbles((previous) => {
        if (!previous[figureId] || previous[figureId].id !== id) {
          return previous;
        }
        const next = { ...previous };
        delete next[figureId];
        return next;
      });
    }, duration);
    bubbleTimers.current.push(timer);
  }, []);

  const hitProject = useCallback(
    (figure, project, now) => {
      const sim = simRef.current;
      const engine = engineRef.current;

      project.damage += 1;
      project.claimedBy = null;
      sceneApiRef.current?.triggerProject(project.key);
      sceneApiRef.current?.triggerFigure(figure.id, "smash");

      if (project.damage >= MAX_DAMAGE) {
        project.dead = true;
        project.removeAt = now + 1000;
        project.claimedBy = null;
        sim.brokenCount += 1;
        setBrokenCount(sim.brokenCount);
        setLastDestroyed({
          key: project.key,
          name: project.repo.name,
          figure: FIGURE_BY_ID[figure.id].name,
          color: FIGURE_BY_ID[figure.id].color,
          at: now,
        });

        sim.figures[figure.id].target = null;

        const shout = SHOUTS[Math.floor(Math.random() * SHOUTS.length)];
        announce(figure.id, {
          text: shout,
          repoName: project.repo.name,
        });
        syncProjects();
        return;
      }

      const line = engine.attack(figure.id, project.repo);
      announce(figure.id, { ...line, repoName: project.repo.name });
      syncProjects();
    },
    [announce, syncProjects]
  );

  const hitRef = useRef(hitProject);
  useEffect(() => {
    hitRef.current = hitProject;
  }, [hitProject]);

  /* -------------------------------------------------------------- */
  /* Ölçüm                                                          */
  /* -------------------------------------------------------------- */

  useEffect(() => {
    const stage = stageRef.current;
    if (!stage) return undefined;

    const measure = () => {
      const rect = stage.getBoundingClientRect();
      if (!rect.width || !rect.height) return;

      const sim = simRef.current;
      const previous = sim.dims;
      const size = figureSize(rect.width);
      const card = cardSize(rect.width);
      sim.dims = { w: rect.width, h: rect.height };

      FIGURES.forEach((figure, index) => {
        const node = sim.figures[figure.id];
        if (!node) {
          const spots = [
            [0.12, 0.18],
            [0.38, 0.16],
            [0.64, 0.16],
            [0.88, 0.2],
            [0.12, 0.82],
            [0.38, 0.84],
            [0.64, 0.84],
            [0.88, 0.8],
          ];
          const [fx, fy] = spots[index] || [0.5, 0.55];
          sim.figures[figure.id] = {
            id: figure.id,
            x: rect.width * fx,
            y: rect.height * fy,
            homeX: fx,
            homeY: fy,
            size,
            vx: 0,
            vy: 0,
            target: null,
            specialTarget: null,
            mode: "roam",
            modeTimer: randomBetween(0.35, 1.8),
            wanderX: rect.width * fx,
            wanderY: rect.height * fy,
            pauseTimer: 0,
            burst: 1,
            motionPhase: Math.random() * Math.PI * 2,
            cooldown: Math.random() * 1.4,
            banterAt: 0,
            nextAuditAt:
              performance.now() + randomBetween(9000, 15000),
          };
        } else {
          node.size = size;
          node.x = clamp(node.x, size / 2 + 8, rect.width - size / 2 - 8);
          node.y = clamp(node.y, size / 2 + 8, rect.height - size / 2 - 8);
        }
      });

      sim.projects.forEach((project) => {
        project.w = card.w;
        project.h = card.h;
        project.x = clamp(
          project.x,
          card.w / 2 + 14,
          rect.width - card.w / 2 - 14
        );
        project.y = clamp(
          project.y,
          card.h / 2 + 14,
          rect.height - card.h / 2 - 14
        );
      });

      if (previous.w && previous.h && sim.projects.length) syncProjects();
    };

    measure();

    const observer =
      typeof ResizeObserver !== "undefined" ? new ResizeObserver(measure) : null;
    if (observer) observer.observe(stage);
    window.addEventListener("resize", measure);

    return () => {
      if (observer) observer.disconnect();
      window.removeEventListener("resize", measure);
    };
  }, [syncProjects]);

  /* -------------------------------------------------------------- */
  /* Simülasyon                                                     */
  /* -------------------------------------------------------------- */

  useEffect(() => {
    const sim = simRef.current;
    const engine = engineRef.current;

    const activeRepos = () =>
      sim.projects.filter((project) => !project.dead).map((p) => p.repo.name);

    const addProject = () => {
      const dims = sim.dims;
      if (!dims.w || !dims.h) return null;

      const mobile = dims.w < 720;
      const card = cardSize(dims.w);
      const used = activeRepos();
      const available = REPOS.filter((repo) => !used.includes(repo.name));
      const pool = available.length ? available : REPOS;
      const repo = pool[Math.floor(Math.random() * pool.length)];

      const slots = projectSlots(dims.w, mobile ? 2 : 4);
      const others = sim.projects.filter((project) => !project.dead);
      let best = null;
      let bestScore = Infinity;

      slots.forEach(([fx, fy]) => {
        const x = clamp(
          dims.w * fx + randomBetween(-14, 14),
          card.w / 2 + 16,
          dims.w - card.w / 2 - 16
        );
        const y = clamp(
          dims.h * fy + randomBetween(-12, 12),
          card.h / 2 + 16,
          dims.h - card.h / 2 - 16
        );

        let score = 0;
        others.forEach((other) => {
          const distance = Math.hypot(other.x - x, other.y - y);
          if (distance < (card.w + other.w) * 0.72) {
            score += 1000 - distance;
          }
        });
        if (score < bestScore) {
          bestScore = score;
          best = { x, y };
        }
      });

      const project = {
        key: `p${sim.projectSeq++}`,
        repo,
        x: best ? best.x : dims.w / 2,
        y: best ? best.y : dims.h / 2,
        w: card.w,
        h: card.h,
        rot: randomBetween(-2.4, 2.4),
        damage: 0,
        dead: false,
        removeAt: 0,
        claimedBy: null,
      };

      sim.projects.push(project);
      return project;
    };

    const desiredCount = () => (sim.dims.w < 720 ? 2 : 3);

    if (!sim.projects.length) {
      for (let index = 0; index < desiredCount(); index += 1) addProject();
      syncProjects();
    }

    const maybeBanter = (first, second, now) => {
      if (now < first.banterAt || now < second.banterAt) return;
      if (Math.random() > 0.35) return;

      const a = FIGURE_BY_ID[first.id];
      const b = FIGURE_BY_ID[second.id];
      const speaker = Math.random() < 0.5 ? first : second;
      const other = speaker === first ? second : first;
      const text = engine.banter(speaker.id, other.id);
      if (!text) return;

      first.banterAt = now + 9000;
      second.banterAt = now + 9000;
      announce(speaker.id, {
        text,
        targetName: (speaker === first ? b : a).name,
      });
    };

    const step = (dt, now) => {
      if (!sim.dims.w) return;
      const dims = sim.dims;

      // Ölmüş kartları temizle ve yerine yenisini koy.
        for (let index = sim.projects.length - 1; index >= 0; index -= 1) {
          const project = sim.projects[index];
          if (project.dead && now >= project.removeAt) {
            sim.projects.splice(index, 1);
          }
        }
        while (
          sim.projects.filter((project) => !project.dead).length <
          desiredCount()
        ) {
          if (!addProject()) break;
        }

        const alive = sim.projects.filter((project) => !project.dead);

        FIGURES.forEach((figure) => {
          const node = sim.figures[figure.id];
          if (!node) return;

          node.cooldown -= dt;
          const motion = figure.motion || {};

          if (node.specialTarget) {
            const action = node.specialTarget;
            if (action.phase === "approach") {
              const distance = steerNode(
                node,
                action.x,
                action.y,
                102,
                dt,
                now,
                { turn: 3.2 }
              );
              if (distance < 24) {
                action.phase = "pressed";
                action.timer = 0.76;
                node.vx = 0;
                node.vy = 0;
                setStopButtonState("pressed");
                sceneApiRef.current?.triggerFigure("altman", "press");
                sceneApiRef.current?.triggerStop();
                announce("altman", {
                  text: "Bastım. Umarım sistem de bunu anlamıştır.",
                  kind: "meme",
                });
              }
            } else {
              action.timer -= dt;
              node.vx *= 0.68;
              node.vy *= 0.68;
              if (action.timer <= 0) {
                node.specialTarget = null;
                node.modeTimer = 0;
                setStopButtonState("ready");
              }
            }
          } else if (node.mode === "recoil") {
            node.modeTimer -= dt;
            node.x += node.vx * dt;
            node.y += node.vy * dt;
            node.vx *= 0.9;
            node.vy *= 0.9;
            if (node.modeTimer <= 0) node.mode = "roam";
          } else {
            let target = sim.projects.find(
              (project) => project.key === node.target
            );
            if (target && (target.dead || target.claimedBy !== node.id)) {
              target = null;
              node.target = null;
            }

            if (!target) {
              const free = alive.filter(
                (project) =>
                  !project.dead &&
                  (!project.claimedBy || project.claimedBy === node.id)
              );
              if (free.length) {
                target = free.reduce((nearest, project) => {
                  const current = Math.hypot(
                    project.x - node.x,
                    project.y - node.y
                  );
                  if (!nearest) return project;
                  const best = Math.hypot(
                    nearest.x - node.x,
                    nearest.y - node.y
                  );
                  return current < best ? project : nearest;
                }, null);

                // Bir maskot aynı anda tek repoyu hedeflesin.
                sim.projects.forEach((project) => {
                  if (
                    project !== target &&
                    project.claimedBy === node.id &&
                    !project.dead
                  ) {
                    project.claimedBy = null;
                  }
                });

                target.claimedBy = node.id;
                node.target = target.key;
              }
            }

            if (target) {
              const dx = target.x - node.x;
              const dy = target.y - node.y;
              const distance = Math.hypot(dx, dy) || 1;
              const stop =
                Math.hypot(target.w, target.h) / 2 + node.size * 0.5 + 6;

              if (distance <= stop + 12 && node.cooldown <= 0) {
                hitRef.current(node, target, now);
                node.mode = "recoil";
                node.modeTimer = randomBetween(0.42, 0.62);
                node.cooldown = randomBetween(0.9, 1.4);
                node.vx = (-dx / distance) * randomBetween(110, 180);
                node.vy = (-dy / distance) * randomBetween(110, 180);
                node.target = null;
              } else {
                const speed = (sim.chaos ? 168 : 82) * (distance < 180 ? 1.14 : 1);
                steerNode(node, target.x, target.y, speed, dt, now, motion);
              }
            } else {
              node.modeTimer -= dt;
              if (node.modeTimer <= 0) {
                const rangeX = dims.w * (motion.coverageX || 0.78);
                const rangeY = dims.h * (motion.coverageY || 0.64);
                node.wanderX = randomBetween(
                  Math.max(node.size, (dims.w - rangeX) / 2),
                  Math.min(dims.w - node.size, (dims.w + rangeX) / 2)
                );
                node.wanderY = randomBetween(
                  Math.max(node.size, (dims.h - rangeY) / 2),
                  Math.min(dims.h - node.size, (dims.h + rangeY) / 2)
                );
                node.modeTimer = randomBetween(
                  motion.walkMin || 1.8,
                  motion.walkMax || 3.6
                );
                node.pauseTimer = Math.random() < (motion.idle || 0.12)
                  ? randomBetween(0.35, 1.05)
                  : 0;
                node.burst = motion.burst && Math.random() < motion.burst
                  ? randomBetween(1.5, 2.05)
                  : 1;
              }
              if (node.pauseTimer > 0) {
                node.pauseTimer -= dt;
                node.vx *= 0.82;
                node.vy *= 0.82;
              } else {
                const speed = (sim.chaos ? 112 : motion.speed || 42) * node.burst;
                steerNode(node, node.wanderX, node.wanderY, speed, dt, now, motion);
              }
            }
          }

          if (
            figure.id === "amodei" &&
            now >= node.nextAuditAt &&
            !node.specialTarget &&
            node.mode !== "recoil"
          ) {
            node.nextAuditAt = now + randomBetween(22000, 32000);
            sceneApiRef.current?.triggerFigure("amodei", "audit");
            announce("amodei", {
              text: "We must slow the pace at which we improve the capabilities of AI models.",
              kind: "quote",
            });
          }

          const pad = node.size / 2 + 8;
          if (node.x < pad) {
            node.x = pad;
            node.vx = Math.abs(node.vx) * 0.5;
          }
          if (node.x > dims.w - pad) {
            node.x = dims.w - pad;
            node.vx = -Math.abs(node.vx) * 0.5;
          }
          if (node.y < pad) {
            node.y = pad;
            node.vy = Math.abs(node.vy) * 0.5;
          }
          if (node.y > dims.h - pad) {
            node.y = dims.h - pad;
            node.vy = -Math.abs(node.vy) * 0.5;
          }
        });

        // Her maskot aynı anda yalnızca tek bir repoyu sahiplensin:
        // sahiplik yalnızca maskotun gerçek hedefi için geçerli.
        sim.projects.forEach((project) => {
          if (!project.claimedBy) return;
          const node = sim.figures[project.claimedBy];
          if (!node || node.target !== project.key) {
            project.claimedBy = null;
          }
        });

        // Maskotlar birbirinin içine girmesin; yaklaşınca laf sokarlar.
        FIGURES.forEach((figure, index) => {
          const node = sim.figures[figure.id];
          if (!node) return;
          FIGURES.slice(index + 1).forEach((otherFigure) => {
            const other = sim.figures[otherFigure.id];
            if (!other) return;
            const dx = other.x - node.x;
            const dy = other.y - node.y;
            const distance = Math.hypot(dx, dy) || 1;
            const min = (node.size + other.size) * 0.62;
            if (distance >= min) return;

            const push = (min - distance) / 2;
            const nx = dx / distance;
            const ny = dy / distance;
            node.x -= nx * push;
            node.y -= ny * push;
            other.x += nx * push;
            other.y += ny * push;

            if (distance < min * 0.92) maybeBanter(node, other, now);
          });
        });

        // Claim edilen kartların rengi değiştiyse arayüze yansıt.
        const claimSignature = sim.projects
          .map((project) => `${project.key}:${project.claimedBy || "-"}:${project.damage}`)
          .join("|");
        if (claimSignature !== sim.claimSignature) {
          sim.claimSignature = claimSignature;
          syncProjects();
        }
    };

    const paint = () => {
      const sim = simRef.current;
      sceneApiRef.current?.updatePose(
        sim.figures,
        sim.projects,
        sim.dims,
        sim.paused,
        performance.now()
      );
    };

    let frame = 0;
    let last = performance.now();

    const tick = (now) => {
      const dt = Math.min(0.05, (now - last) / 1000);
      last = now;
      if (!sim.paused) step(dt, now);
      paint();
      frame = window.requestAnimationFrame(tick);
    };

    frame = window.requestAnimationFrame(tick);

    if (
      typeof window !== "undefined" &&
      new URLSearchParams(window.location.search).has("debug")
    ) {
      window.__arena = { sim, step, paint, FIGURES };
    }

    return () => window.cancelAnimationFrame(frame);
  }, [reduced, announce, syncProjects]);

  /* -------------------------------------------------------------- */
  /* Klavye                                                         */
  /* -------------------------------------------------------------- */

  useEffect(() => {
    const onKeyDown = (event) => {
      if (event.key === "Escape") {
        setAboutOpen(false);
        setLogOpen(false);
        setQuestionFigureId(null);
        return;
      }

      const tag = (event.target && event.target.tagName) || "";
      if (/^(INPUT|TEXTAREA|SELECT)$/.test(tag)) return;

      if (event.key === " " && !aboutOpen && !logOpen && !questionFigureId) {
        event.preventDefault();
        setPaused((value) => !value);
      }
    };

    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [aboutOpen, logOpen, questionFigureId]);

  const handleProvoke = useCallback(
    (key) => {
      const sim = simRef.current;
      const project = sim.projects.find((item) => item.key === key);
      if (!project || project.dead) return;
      countClick("repo_card_click");

      const candidates = FIGURES.map((figure) => sim.figures[figure.id])
        .filter(Boolean)
        .filter((node) => node.mode !== "recoil")
        .sort(
          (a, b) =>
            Math.hypot(project.x - a.x, project.y - a.y) -
            Math.hypot(project.x - b.x, project.y - b.y)
        );

      const figure = candidates[0];
      if (!figure) return;

      if (project.claimedBy && sim.figures[project.claimedBy]) {
        sim.figures[project.claimedBy].target = null;
      }

      project.claimedBy = figure.id;
      figure.target = project.key;
      figure.mode = "roam";

      announce(figure.id, {
        text: `${project.repo.name} dikkatimi çekti. Birlikte bakalım.`,
        repoName: project.repo.name,
      });
      syncProjects();
      sceneApiRef.current?.triggerFigure(figure.id, "charge");
      sceneApiRef.current?.triggerProject(project.key);
    },
    [announce, syncProjects]
  );

  const askMascot = useCallback((figureId) => {
    countClick("mascot_click");
    setSelectedQuestionId(null);
    setQuestionFigureId(figureId);
  }, []);

  const rotateCamera = useCallback((yaw, pitch) => {
    sceneApiRef.current?.orbit(
      (yaw * Math.PI) / 180,
      (-pitch * Math.PI) / 180
    );
  }, []);

  const resetCamera = useCallback(() => {
    sceneApiRef.current?.resetCamera();
  }, []);

  const handleSamStop = useCallback(() => {
    if (stopButtonState !== "ready") return;

    const stage = stageRef.current;
    const sim = simRef.current;
    const sam = sim.figures.altman;
    if (!stage || !sam) return;
    countClick("stop_button_click");

    const target = sceneApiRef.current?.getStopPoint(sim.dims.w, sim.dims.h);
    if (!target) return;

    sim.projects.forEach((project) => {
      if (project.claimedBy === "altman") project.claimedBy = null;
    });
    sam.target = null;
    sam.specialTarget = {
      x: clamp(target.x, sam.size / 2 + 8, sim.dims.w - sam.size / 2 - 8),
      y: clamp(target.y, sam.size / 2 + 8, sim.dims.h - sam.size / 2 - 8),
      phase: "approach",
      timer: 0,
    };

    sim.paused = false;
    setPaused(false);
    setStopButtonState("approaching");
    announce("altman", { text: "We need to stop.", kind: "meme" });
  }, [announce, stopButtonState]);

  const activeCount = projects.filter((project) => !project.dead).length;
  const questionFigure = questionFigureId
    ? FIGURE_BY_ID[questionFigureId]
    : null;
  const questions = questionFigureId ? QUESTIONS[questionFigureId] || [] : [];
  const selectedQuestion = questions.find(
    (question) => question.id === selectedQuestionId
  );
  const selectedAnswer = selectedQuestion
    ? selectedQuestion.answer.replace(/\{\{repoCount\}\}/g, String(REPOS.length))
    : "";

  return (
    <div className="arena">
      <header className="topbar">
        <div className="brand">
          <span className="brand-mark" aria-hidden="true">
            HA
          </span>
          <div className="brand-text">
            <div className="brand-title">Hüseyin AFŞİN</div>
            <div className="brand-sub">{SITE_KICKER}</div>
          </div>
          <div className="brand-stat">
            <span className="brand-stat__value">{brokenCount}</span>
            <span className="brand-stat__label">repo parçalandı</span>
          </div>
        </div>

        <nav className="controls" aria-label="Sahne kontrolleri">
          <button
            type="button"
            className={`ctl${chaos ? " is-on" : ""}`}
            onClick={() => setChaos((value) => !value)}
            aria-pressed={chaos}
          >
            Hızlı mod
          </button>
          <button
            type="button"
            className={`ctl${paused ? " is-on" : ""}`}
            onClick={() => setPaused((value) => !value)}
            aria-pressed={paused}
          >
            {paused ? "Devam" : "Duraklat"}
          </button>
          <button
            type="button"
            className="ctl"
            onClick={() => {
              countClick("conversation_log_open");
              setLogOpen(true);
            }}
          >
            Konuşmalar
            <span className="ctl-count">{log.length}</span>
          </button>
          <button
            type="button"
            className="ctl ctl--ghost"
            onClick={() => {
              countClick("manifesto_open");
              setAboutOpen(true);
            }}
          >
            Manifesto
          </button>
          <a
            className="ctl github-link"
            href="https://github.com/huseyinafsin"
            target="_blank"
            rel="noopener noreferrer"
          >
            <span className="github-link__full">GitHub hesabım ↗</span>
            <span className="github-link__short">GitHub ↗</span>
          </a>
        </nav>
      </header>

      <main
        className="stage"
        ref={stageRef}
      >
        <LaboratoryScene3D
          sceneRef={sceneApiRef}
          projects={projects}
          bubbles={bubbles}
          stopState={stopButtonState}
          reduced={reduced}
          onFigureClick={askMascot}
          onProjectClick={handleProvoke}
          onStopClick={handleSamStop}
        />

        <div className="stage-frame" aria-hidden="true">
          <i />
          <i />
          <i />
          <i />
        </div>
        <span className="stage-note stage-note--tl">
          Laboratuvar 01 — kodun bedeli
        </span>
        <div className="stage-camera-hud">
          <span className="camera-count">
            {activeCount} repo sırada · kartlar tek tek dağılıyor
          </span>
          <div className="camera-controls" aria-label="Laboratuvar kamerası">
            <button type="button" onClick={() => rotateCamera(-10, 0)} aria-label="Soldan bak">←</button>
            <button type="button" onClick={() => rotateCamera(0, 8)} aria-label="Kamerayı yukarı kaldır">↑</button>
            <button type="button" onClick={() => rotateCamera(0, -8)} aria-label="Kamerayı aşağı indir">↓</button>
            <button type="button" onClick={() => rotateCamera(10, 0)} aria-label="Sağdan bak">→</button>
            <button type="button" className="camera-reset" onClick={resetCamera}>Ön görünüm</button>
          </div>
        </div>
        <span className="stage-note stage-note--bl">
          Sahneyi sürükle: kamerayı döndür · Maskota tıkla: soru sor
        </span>
        {paused && <div className="paused-badge">Duraklatıldı</div>}
      </main>

      <footer className="understage">
        <div className="ticker">
          <span className="ticker-label">Son hareket</span>
          {lastDestroyed ? (
            <span className="ticker-text" key={lastDestroyed.key}>
              <b style={{ color: lastDestroyed.color }}>{lastDestroyed.figure}</b>{" "}
              maskotu, {lastDestroyed.name} kartını parçaladı.
            </span>
          ) : (
            <span className="ticker-text">
              Henüz bir repo kartı parçalanmadı. Sekiz maskot sahnede.
            </span>
          )}
        </div>

        <div className="rail">
          <span className="rail-label">Sıradaki repolar</span>
          <div className="rail-list">
            {projects
              .filter((project) => !project.dead)
              .map((project) => (
                <span className="rail-chip" key={project.key}>
                  {project.repo.name}
                  <i>{MAX_DAMAGE - project.damage}</i>
                </span>
              ))}
          </div>
          <span className="rail-meta">
            {activeCount} repo · {FIGURES.length} maskot
          </span>
        </div>
      </footer>

      {aboutOpen && (
        <div
          className="overlay"
          onClick={(event) => {
            if (event.target === event.currentTarget) setAboutOpen(false);
          }}
          role="dialog"
          aria-modal="true"
          aria-label="Manifesto"
        >
          <div className="dialog">
            <div className="dialog-head">
              <h2 className="dialog-title">Manifesto</h2>
              <button
                type="button"
                className="dialog-close"
                onClick={() => setAboutOpen(false)}
                aria-label="Kapat"
              >
                ✕
              </button>
            </div>
            <div className="dialog-body">
              <p>
                Yazılımcılar açık kodu herkes yararlansın diye paylaştı.
                Yapay zekâ şirketleri bu ortak emeği aldı; şimdi emeği verenleri
                işsiz bırakabilecek sistemleri aynı kodlarla büyütüyor.
              </p>
              <p>
                Kod herkesin erişimine açıldı, ama değeri ve kazancı birkaç
                şirketin elinde toplandı. Geliştiricilere ise kendi emekleriyle
                eğitilen sistemlerle rekabet etmek kaldı.
              </p>
              <p>
                Bir zamanlar geleceği birlikte kurmak için paylaşılan kod,
                bugün onu yazanların işini ortadan kaldırabilir. Bu ilerlemenin
                bedelini kim ödüyor, kazancını kim topluyor?
              </p>
            </div>
          </div>
        </div>
      )}

      {questionFigure && (
        <div
          className="overlay"
          onClick={(event) => {
            if (event.target === event.currentTarget) {
              setQuestionFigureId(null);
              setSelectedQuestionId(null);
            }
          }}
          role="dialog"
          aria-modal="true"
          aria-label={`${questionFigure.name} ile soru-cevap`}
        >
          <div className="dialog question-dialog">
            <div className="dialog-head">
              <div>
                <h2 className="dialog-title">{questionFigure.name}</h2>
                <div className="question-subtitle">
                  Bu maskota ne sormak istersin?
                </div>
              </div>
              <button
                type="button"
                className="dialog-close"
                onClick={() => {
                  setQuestionFigureId(null);
                  setSelectedQuestionId(null);
                }}
                aria-label="Kapat"
              >
                ✕
              </button>
            </div>
            <div className="dialog-body">
              <div className="question-list">
                {questions.map((question, index) => (
                  <button
                    key={question.id}
                    type="button"
                    className={`question-option${
                      selectedQuestionId === question.id ? " is-selected" : ""
                    }`}
                    onClick={() => {
                      countClick("question_click");
                      setSelectedQuestionId(question.id);
                    }}
                    aria-pressed={selectedQuestionId === question.id}
                  >
                    <span>{String(index + 1).padStart(2, "0")}</span>
                    {question.question}
                  </button>
                ))}
              </div>
              {selectedQuestion && (
                <section
                  className="answer-panel"
                  style={{ "--figure-color": questionFigure.color }}
                  aria-live="polite"
                >
                  <div
                    className="answer-speaker"
                    style={{ color: questionFigure.color }}
                  >
                    {questionFigure.name} yanıtlıyor
                  </div>
                  <p className="answer-text">{selectedAnswer}</p>
                </section>
              )}
              <div className="dialog-meta">
                Yanıtlar bu sahne için yazılmıştır; canlı model yanıtı değildir.
              </div>
            </div>
          </div>
        </div>
      )}

      {logOpen && (
        <div
          className="overlay"
          onClick={(event) => {
            if (event.target === event.currentTarget) setLogOpen(false);
          }}
          role="dialog"
          aria-modal="true"
          aria-label="Konuşmalar"
        >
          <div className="dialog">
            <div className="dialog-head">
              <h2 className="dialog-title">Konuşmalar</h2>
              <button
                type="button"
                className="dialog-close"
                onClick={() => setLogOpen(false)}
                aria-label="Kapat"
              >
                ✕
              </button>
            </div>
            <div className="dialog-body">
              {log.length === 0 ? (
                <div className="log-empty">
                  Henüz konuşan olmadı.
                </div>
              ) : (
                <div className="log-list">
                  {log.map((entry) => {
                    const figure = FIGURE_BY_ID[entry.figureId];
                    return (
                      <div className="log-row" key={entry.id}>
                        <div className="log-meta">
                          <b style={{ color: figure ? figure.color : undefined }}>
                            {figure ? figure.name : "?"}
                          </b>
                          {entry.time.toLocaleTimeString("tr-TR", {
                            hour: "2-digit",
                            minute: "2-digit",
                          })}
                        </div>
                        <div className="log-text">
                          {entry.text}
                          {entry.repoName && (
                            <span className="log-repo">
                              hedef: {entry.repoName}
                            </span>
                          )}
                          {entry.targetName && (
                            <span className="log-repo">
                              → {entry.targetName}
                            </span>
                          )}
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default Arena;
