import { ATTACK_LINES, MUTTERS, BANTER } from "./lines";
import { FIGURE_BY_ID } from "./figures";

function shuffle(list) {
  const copy = list.slice();
  for (let index = copy.length - 1; index > 0; index -= 1) {
    const random = Math.floor(Math.random() * (index + 1));
    [copy[index], copy[random]] = [copy[random], copy[index]];
  }
  return copy;
}

function fill(template, repo = {}) {
  return template
    .replace(/\{\{repo\}\}/g, repo.name || "bu repo")
    .replace(/\{\{lang\}\}/g, repo.lang || "bilinmeyen bir dil")
    .replace(/\{\{stars\}\}/g, String(repo.stars || 0))
    .replace(/\{\{desc\}\}/g, repo.desc || "")
    .replace(/\{\{other\}\}/g, repo.other || "sen");
}

/**
 * Konuşma havuzlarını karıştırır, aynı cümleyi kısa sürede tekrar ettirmez
 * ve repoya özel satırlarda açıklama şartını kontrol eder.
 */
export default class DeliveryEngine {
  constructor() {
    this.queues = {};
    this.recent = {};
  }

  remember(key, text) {
    const list = this.recent[key] || [];
    this.recent[key] = [...list.slice(-11), text];
  }

  isRecent(key, text) {
    return (this.recent[key] || []).includes(text);
  }

  takeFromPool(key, pool, repo) {
    if (!this.queues[key] || this.queues[key].length === 0) {
      this.queues[key] = shuffle(pool);
    }

    for (let attempt = 0; attempt < pool.length; attempt += 1) {
      const template = this.queues[key].shift();
      if (!template) continue;
      if (template.includes("{{desc}}") && !repo.desc) continue;

      const text = fill(template, repo);
      if (this.isRecent(key, text)) continue;
      this.remember(key, text);
      return text;
    }

    const fallback = fill(pool[0], repo);
    this.remember(key, fallback);
    return fallback;
  }

  attack(figureId, repo) {
    const useMutter = Math.random() < 0.18;
    const pool = useMutter ? MUTTERS[figureId] : ATTACK_LINES[figureId];
    const kind = useMutter ? "mutter" : "attack";
    return {
      text: this.takeFromPool(`${figureId}:${kind}`, pool, repo),
      kind,
    };
  }

  banter(speakerId, otherId) {
    const matching = BANTER.filter(
      (item) =>
        item.from === speakerId && (item.to === otherId || item.to === "*")
    );
    const exact = matching.filter((item) => item.to === otherId);
    const options = exact.length ? exact : matching;
    const fresh = options.filter(
      (item) => !this.isRecent(`banter:${speakerId}:${otherId}`, item.text)
    );
    if (!fresh.length) return null;

    const item = fresh[Math.floor(Math.random() * fresh.length)];
    const other = FIGURE_BY_ID[otherId];
    const text = fill(item.text, { other: other ? other.name : "sen" });
    this.remember(`banter:${speakerId}:${otherId}`, item.text);
    return text;
  }
}
