const COUNTER_ENDPOINT = (
  process.env.REACT_APP_CLICK_COUNTER_ENDPOINT || ""
).replace(/\/+$/, "");

const ALLOWED_EVENTS = new Set([
  "page_view",
  "mascot_click",
  "repo_card_click",
  "question_click",
  "stop_button_click",
  "manifesto_open",
  "conversation_log_open",
]);

/** Sends only a fixed event name; it never sends visitor or device details. */
export function countClick(eventName) {
  if (
    !COUNTER_ENDPOINT ||
    !ALLOWED_EVENTS.has(eventName) ||
    typeof window === "undefined" ||
    typeof window.fetch !== "function"
  ) {
    return;
  }

  try {
    window
      .fetch(`${COUNTER_ENDPOINT}/count`, {
        method: "POST",
        mode: "cors",
        credentials: "omit",
        referrerPolicy: "no-referrer",
        keepalive: true,
        headers: { "Content-Type": "text/plain;charset=UTF-8" },
        body: eventName,
      })
      .catch(() => {});
  } catch (_) {
    // Analytics must never interrupt the scene.
  }
}
